parameters.query:
SELECT DISTINCT ON (workflow_name, stage_name) workflow_name, stage_name, status, started_at, finished_at,
       duration_ms, retry_count, error_message, warning_count, error_count
FROM trading.pipeline_runs ORDER BY workflow_name, stage_name, started_at DESC;

parameters.jsCode:
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function esc(s) {
  return safeStr(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function num(v) {
  const n = Number(v);
  return isNaN(n) ? null : n;
}
function rows(nodeName) {
  try { return $(nodeName).all().map(i => i.json || {}); } catch (e) { return []; }
}

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}
const heute = getBusinessDate();
const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const fundamentaldaten = rows('DB: Fundamentaldaten laden');
const marktKontext     = rows('DB: Marktumfeld laden');
const techSignale      = rows('DB: Technische Signale laden');
const news             = rows('DB: News laden (trading.*)').map(r => ({ datum_iso: r.published_at || r.created_at, relevanz: r.wirkung_staerke === 'hoch' ? 'hoch' : (r.wirkung_staerke === 'mittel' ? 'mittel' : '') }));
const empfehlungen     = rows('DB: Empfehlungen laden');
const kursHistorie     = rows('DB: Kursverlauf laden');

function letzterStand(list, getFeld) {
  const daten = list.map(r => safeStr(getFeld(r))).filter(Boolean).sort();
  return daten.length > 0 ? daten[daten.length - 1] : null;
}

function quelleZeile(name, list, getFeld) {
  const stand = letzterStand(list, getFeld);
  const standDatum = stand ? stand.substring(0, 10) : null;
  const aktuell = standDatum === heute;
  const badge = list.length === 0
    ? '<span class="badge warn">leer</span>'
    : aktuell
      ? '<span class="badge ok">aktuell</span>'
      : '<span class="badge warn">veraltet (' + esc(standDatum || 'unbekannt') + ')</span>';
  return '<tr><td>' + esc(name) + '</td><td class="num">' + list.length + '</td><td>' + (stand ? esc(stand) : '—') + '</td><td>' + badge + '</td></tr>';
}

const quellenHtml =
  quelleZeile('stock_fundamentals', fundamentaldaten, r => r.datum) +
  quelleZeile('stock_market_context', marktKontext, r => r.datum) +
  quelleZeile('stock_technical_signals', techSignale, r => r.datum) +
  quelleZeile('stock_news_evaluated', news, r => r.datum_iso || r.datum) +
  quelleZeile('stock_empfehlungen', empfehlungen, r => r.letzte_aktualisierung) +
  quelleZeile('stock_price_history', kursHistorie, r => r.datum);

// Technische Signale heute
const techHeute = techSignale.filter(s => safeStr(s.datum).startsWith(heute));
const handelskandidaten = techHeute.filter(s => s.handels_status === 'handelskandidat');
const beobachten = techHeute.filter(s => s.handels_status === 'beobachten');

function signalZeile(s) {
  return '<tr><td>' + esc(s.ticker) + '</td><td>' + esc(s.name) + '</td><td>' + esc(s.handels_status_text || s.handels_status) + '</td>' +
    '<td class="num">' + esc(s.rsi) + '</td><td>' + esc(s.macd_signal) + '</td><td>' + esc(s.richtung) + '</td></tr>';
}
const kandidatenHtml = handelskandidaten.length > 0 ? handelskandidaten.map(signalZeile).join('') : '<tr><td colspan="6" class="empty">keine heute</td></tr>';
const beobachtenHtml = beobachten.length > 0 ? beobachten.map(signalZeile).join('') : '<tr><td colspan="6" class="empty">keine heute</td></tr>';

// Empfehlungs-Watchlist
const offen = empfehlungen.filter(e => e.status === 'offen');
const geschlossen = empfehlungen.filter(e => e.status === 'geschlossen');
const perfWerte = geschlossen.map(e => num(e.performance_pct)).filter(v => v !== null);
const avgPerf = perfWerte.length > 0 ? (perfWerte.reduce((a, b) => a + b, 0) / perfWerte.length).toFixed(2) : null;
const hitRate = perfWerte.length > 0 ? Math.round((perfWerte.filter(v => v > 0).length / perfWerte.length) * 100) : null;

function empfehlungZeile(e) {
  return '<tr><td>' + esc(e.ticker) + '</td><td>' + esc(e.richtung) + '</td><td>' + esc(e.entry_datum) + '</td>' +
    '<td class="num">' + esc(e.entry_kurs) + '</td><td>' + esc(e.status) + '</td></tr>';
}
const offenHtml = offen.length > 0 ? offen.map(empfehlungZeile).join('') : '<tr><td colspan="5" class="empty">keine offenen Positionen</td></tr>';

// News heute
const newsHeute = news.filter(n => safeStr(n.datum_iso || n.datum).startsWith(heute));
const newsHoch = newsHeute.filter(n => n.relevanz === 'hoch').length;
const newsMittel = newsHeute.filter(n => n.relevanz === 'mittel').length;

const html = '<!DOCTYPE html>' +
'<html lang="de">' +
'<head>' +
'<meta charset="utf-8">' +
'<title>Aktien-Pipeline Status-Uebersicht</title>' +
'<style>' +
'  body { font-family: -apple-system, Segoe UI, Arial, sans-serif; background:#0f1115; color:#e6e6e6; margin:0; padding:32px; }' +
'  h1 { font-size:20px; margin-bottom:4px; }' +
'  .meta { color:#9aa0a6; font-size:13px; margin-bottom:24px; }' +
'  table { border-collapse: collapse; width:100%; margin-bottom:32px; }' +
'  th, td { text-align:left; padding:8px 12px; border-bottom:1px solid #2a2d34; font-size:14px; font-variant-numeric: tabular-nums; }' +
'  th { color:#9aa0a6; font-weight:600; font-size:12px; text-transform:uppercase; letter-spacing:0.04em; }' +
'  td.num { text-align:right; }' +
'  .empty { color:#5f6368; font-style:italic; }' +
'  h2 { font-size:15px; margin-top:8px; margin-bottom:8px; color:#e6e6e6; }' +
'  .hint { color:#9aa0a6; font-size:12px; margin-bottom:12px; }' +
'  .badge { display:inline-block; padding:2px 8px; border-radius:999px; font-size:11px; font-weight:600; }' +
'  .badge.ok { background:#1c3a2a; color:#6bcf8e; }' +
'  .badge.warn { background:#3a2c1c; color:#e0a854; }' +
'  .summary { display:flex; gap:16px; margin-bottom:24px; flex-wrap:wrap; }' +
'  .stat { background:#181b21; border:1px solid #2a2d34; border-radius:8px; padding:12px 16px; min-width:140px; }' +
'  .stat .label { color:#9aa0a6; font-size:11px; text-transform:uppercase; letter-spacing:0.04em; margin-bottom:4px; }' +
'  .stat .value { font-size:22px; font-weight:700; font-variant-numeric: tabular-nums; }' +
'  .stat .value.good { color:#6bcf8e; }' +
'  .stat .value.bad { color:#e0665a; }' +
'  .section-divider { margin:40px 0 20px; padding-bottom:8px; border-bottom:2px solid #2a2d34; font-size:13px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:#5b8def; }' +
'</style>' +
'</head>' +
'<body>' +
'  <h1>Aktien-Report-Pipeline &mdash; Status-Uebersicht</h1>' +
'  <div class="meta">Stand: ' + esc(now) + '</div>' +
'  <div class="section-divider">📈 Geschäftskennzahlen</div>' +
'  <h2>Kennzahlen heute</h2>' +
'  <div class="summary">' +
'    <div class="stat"><div class="label">Handelskandidaten</div><div class="value">' + handelskandidaten.length + '</div></div>' +
'    <div class="stat"><div class="label">Beobachten</div><div class="value">' + beobachten.length + '</div></div>' +
'    <div class="stat"><div class="label">News hoch/mittel</div><div class="value">' + newsHoch + ' / ' + newsMittel + '</div></div>' +
'    <div class="stat"><div class="label">Offene Empfehlungen</div><div class="value">' + offen.length + '</div></div>' +
'    <div class="stat"><div class="label">Ø Performance geschlossen</div><div class="value ' + (avgPerf !== null && avgPerf >= 0 ? 'good' : avgPerf !== null ? 'bad' : '') + '">' + (avgPerf !== null ? avgPerf + '%' : '—') + '</div></div>' +
'    <div class="stat"><div class="label">Trefferquote</div><div class="value">' + (hitRate !== null ? hitRate + '%' : '—') + '</div></div>' +
'  </div>' +
'  <h2>Handelskandidaten heute</h2>' +
'  <table>' +
'    <thead><tr><th>Ticker</th><th>Name</th><th>Status</th><th>RSI</th><th>MACD</th><th>Richtung</th></tr></thead>' +
'    <tbody>' + kandidatenHtml + '</tbody>' +
'  </table>' +
'  <h2>Beobachten heute</h2>' +
'  <table>' +
'    <thead><tr><th>Ticker</th><th>Name</th><th>Status</th><th>RSI</th><th>MACD</th><th>Richtung</th></tr></thead>' +
'    <tbody>' + beobachtenHtml + '</tbody>' +
'  </table>' +
'  <h2>Offene Empfehlungs-Positionen</h2>' +
'  <div class="hint">Hypothetische Watchlist aus News+Signal-Treffern, keine echten Trades.</div>' +
'  <table>' +
'    <thead><tr><th>Ticker</th><th>Richtung</th><th>Entry-Datum</th><th>Entry-Kurs</th><th>Status</th></tr></thead>' +
'    <tbody>' + offenHtml + '</tbody>' +
'  </table>' +
'</body>' +
'</html>';

// ─── Phase 13: Orchestrator-/Agenten-/Lernprozess-Kennzahlen ──────────────────
const pipelineLaeufe = rows('DB: Letzte Pipeline-Laeufe je Stufe');
const letzterErfolg = rows('DB: Letzter erfolgreicher Lauf je Workflow');
const agentLaeufe = rows('DB: Letzter Lauf je Agent');
const newsZustand = rows('DB: News-Zustandsverteilung');
const wirkungsFortschritt = rows('DB: Wirkungsanalyse-Fortschritt');
const lernVorschlaege = rows('DB: Offene Lernvorschlaege')[0] || {};
const pipelineConfig = rows('DB: Pipeline-Konfiguration laden');

function pipelineZeile(p) {
  const erfolgTreffer = letzterErfolg.find(e => e.workflow_name === p.workflow_name);
  const badge = p.status === 'success' ? '<span class="badge ok">success</span>'
    : p.status === 'failed' ? '<span class="badge warn">failed</span>'
    : '<span class="badge warn">' + esc(p.status) + '</span>';
  return '<tr><td>' + esc(p.workflow_name) + '</td><td>' + esc(p.stage_name) + '</td><td>' + badge + '</td>' +
    '<td>' + esc(p.finished_at) + '</td><td>' + esc(erfolgTreffer ? erfolgTreffer.finished_at : '—') + '</td>' +
    '<td class="num">' + esc(p.duration_ms) + '</td><td class="num">' + esc(p.retry_count || 0) + '</td>' +
    '<td class="num">' + esc(p.warning_count || 0) + '</td><td class="num">' + esc(p.error_count || 0) + '</td></tr>';
}
const pipelineHtml = pipelineLaeufe.length > 0 ? pipelineLaeufe.map(pipelineZeile).join('') : '<tr><td colspan="9" class="empty">noch keine Orchestrator-Laeufe protokolliert</td></tr>';

function agentZeile(a) {
  const badge = a.status === 'success' ? '<span class="badge ok">success</span>' : '<span class="badge warn">' + esc(a.status) + '</span>';
  return '<tr><td>' + esc(a.agent_name) + '</td><td>' + esc(a.model_name) + '</td><td>' + esc(a.prompt_version) + '</td>' +
    '<td>' + badge + '</td><td>' + esc(a.started_at) + '</td><td class="num">' + esc(a.confidence ?? '') + '</td></tr>';
}
const agentHtml = agentLaeufe.length > 0 ? agentLaeufe.map(agentZeile).join('') : '<tr><td colspan="6" class="empty">noch keine Agentenlaeufe protokolliert</td></tr>';

const trefferquoteJeQuelle = rows('DB: Trefferquote je Quelle');

function configWert(c) {
  if (c.value_bool !== null && c.value_bool !== undefined) return String(c.value_bool);
  if (c.value_numeric !== null && c.value_numeric !== undefined) return String(c.value_numeric);
  if (c.value_text !== null && c.value_text !== undefined && c.value_text !== '') return c.value_text;
  return '—';
}
function configZeile(c) {
  return '<tr><td>' + esc(c.config_key) + '</td><td>' + esc(configWert(c)) + '</td>' +
    '<td>' + esc(c.description) + '</td><td>' + esc(c.updated_at) + '</td></tr>';
}
const configHtml = pipelineConfig.length > 0 ? pipelineConfig.map(configZeile).join('') : '<tr><td colspan="4" class="empty">trading.pipeline_config leer</td></tr>';

// ─── Einfache horizontale Balkendiagramme, reines SVG, kein externer Dienst ──
function escSvg(v) { return String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function svgBarChart(rowsIn, opts) {
  opts = opts || {};
  const width = opts.width || 640;
  const barHeight = 20;
  const gap = 10;
  const labelWidth = opts.labelWidth || 170;
  const chartWidth = width - labelWidth - 60;
  const maxVal = opts.maxValue || Math.max(1, ...rowsIn.map(r => Number(r.value) || 0));
  const height = rowsIn.length * (barHeight + gap) + gap;
  let svg = '<svg viewBox="0 0 ' + width + ' ' + height + '" width="100%" style="max-width:' + width + 'px;height:auto" xmlns="http://www.w3.org/2000/svg">';
  rowsIn.forEach((r, i) => {
    const y = gap + i * (barHeight + gap);
    const val = Number(r.value) || 0;
    const barW = Math.max(2, (val / maxVal) * chartWidth);
    const color = r.color || '#6bcf8e';
    svg += '<text x="0" y="' + (y + barHeight / 2 + 4) + '" fill="#9aa0a6" font-size="12">' + escSvg(r.label) + '</text>';
    svg += '<rect x="' + labelWidth + '" y="' + y + '" width="' + barW + '" height="' + barHeight + '" rx="4" fill="' + color + '"/>';
    svg += '<text x="' + (labelWidth + barW + 8) + '" y="' + (y + barHeight / 2 + 4) + '" fill="#e6e6e6" font-size="12">' + escSvg(r.valueText != null ? r.valueText : r.value) + '</text>';
  });
  svg += '</svg>';
  return svg;
}
function trefferquoteColor(pct) {
  if (pct === null || pct === undefined) return '#5f6368';
  if (pct >= 60) return '#6bcf8e';
  if (pct >= 40) return '#e0a854';
  return '#e0665a';
}

const wirkungsChartRows = wirkungsFortschritt
  .filter(w => Number(w.anzahl) > 0)
  .map(w => ({ label: w.status, value: Number(w.anzahl), valueText: w.anzahl, color: w.status === 'completed' ? '#6bcf8e' : (w.status === 'confounded' ? '#e0665a' : '#4a90d9') }));
const wirkungsChartHtml = wirkungsChartRows.length > 0
  ? svgBarChart(wirkungsChartRows, {})
  : '<p class="empty">noch keine Wirkungsanalyse-Daten</p>';

const trefferquoteChartRows = trefferquoteJeQuelle
  .filter(q => q.trefferquote !== null && q.trefferquote !== undefined)
  .map(q => ({ label: q.value + ' (n=' + q.sample_size + ')', value: Number(q.trefferquote), valueText: q.trefferquote + '%', color: trefferquoteColor(Number(q.trefferquote)) }));
const trefferquoteChartHtml = trefferquoteChartRows.length > 0
  ? svgBarChart(trefferquoteChartRows, { maxValue: 100 })
  : '<p class="empty">noch keine abgeschlossenen Wirkungsanalysen je Quelle (mindestens 1 abgeschlossener Fall noetig)</p>';

const newsZustandMap = {};
for (const z of newsZustand) newsZustandMap[z.status] = Number(z.anzahl);
const newsOffenRetry = (newsZustandMap.pending || 0) + (newsZustandMap.retry || 0);
const newsFailed = newsZustandMap.failed || 0;

const impactMap = {};
for (const w of wirkungsFortschritt) impactMap[w.status] = w;
const impactCompleted = impactMap.completed || { anzahl: 0, trefferquote: null };
const impactConfounded = wirkungsFortschritt.reduce((sum, w) => sum + Number(w.confounded_anzahl || 0), 0);
const impactOffen = wirkungsFortschritt.filter(w => String(w.status).startsWith('waiting_')).reduce((sum, w) => sum + Number(w.anzahl || 0), 0);

const zusatzHtml =
'  <div class="section-divider">⚙️ Betrieb &amp; Pipeline-Status</div>' +
'  <h2>Datenquellen</h2>' +
'  <table>' +
'    <thead><tr><th>Tabelle</th><th>Zeilen</th><th>Letzter Stand</th><th></th></tr></thead>' +
'    <tbody>' + quellenHtml + '</tbody>' +
'  </table>' +
'  <h2>Orchestrator-Laeufe (letzter Lauf je Stufe)</h2>' +
'  <table><thead><tr><th>Workflow</th><th>Stufe</th><th>Status</th><th>Beendet</th><th>Letzter Erfolg</th><th>Dauer (ms)</th><th>Retries</th><th>Warnungen</th><th>Fehler</th></tr></thead>' +
'    <tbody>' + pipelineHtml + '</tbody></table>' +
'  <h2>Agentenlaeufe (letzter Lauf je Agent)</h2>' +
'  <table><thead><tr><th>Agent</th><th>Modell</th><th>Prompt-Version</th><th>Status</th><th>Gestartet</th><th>Konfidenz</th></tr></thead>' +
'    <tbody>' + agentHtml + '</tbody></table>' +
'  <h2>News-Verarbeitung &amp; Wirkungsanalyse</h2>' +
'  <div class="summary">' +
'    <div class="stat"><div class="label">Offene News-Retries</div><div class="value ' + (newsOffenRetry > 20 ? 'bad' : '') + '">' + newsOffenRetry + '</div></div>' +
'    <div class="stat"><div class="label">Fehlgeschlagene News</div><div class="value ' + (newsFailed > 0 ? 'bad' : '') + '">' + newsFailed + '</div></div>' +
'    <div class="stat"><div class="label">Offene Wirkungsanalysen</div><div class="value">' + impactOffen + '</div></div>' +
'    <div class="stat"><div class="label">Abgeschlossene D+1..D+20</div><div class="value">' + impactCompleted.anzahl + '</div></div>' +
'    <div class="stat"><div class="label">Trefferquote (sauber)</div><div class="value">' + (impactCompleted.trefferquote !== null && impactCompleted.trefferquote !== undefined ? impactCompleted.trefferquote + '%' : '—') + '</div></div>' +
'    <div class="stat"><div class="label">Konfundierte Faelle</div><div class="value">' + impactConfounded + '</div></div>' +
'  </div>' +
'  <h2>Wirkungsanalyse -- Status-Verteilung</h2>' +
'  <div style="background:#181b21;border:1px solid #2a2d34;border-radius:8px;padding:16px;margin-bottom:24px;overflow-x:auto">' + wirkungsChartHtml + '</div>' +
'  <h2>Trefferquote je Quelle (abgeschlossene, unverunreinigte Faelle)</h2>' +
'  <div style="background:#181b21;border:1px solid #2a2d34;border-radius:8px;padding:16px;margin-bottom:24px;overflow-x:auto">' + trefferquoteChartHtml + '</div>' +
'  <h2>Lernagent</h2>' +
'  <div class="summary">' +
'    <div class="stat"><div class="label">Offene Lernvorschlaege</div><div class="value">' + (lernVorschlaege.offene_vorschlaege || 0) + '</div></div>' +
'    <div class="stat"><div class="label">Letzter Vorschlag am</div><div class="value" style="font-size:14px">' + esc(lernVorschlaege.letzter_vorschlag_am || '—') + '</div></div>' +
'  </div>' +
'  <h2>Konfiguration (trading.pipeline_config)</h2>' +
'  <table><thead><tr><th>Key</th><th>Wert</th><th>Beschreibung</th><th>Zuletzt geaendert</th></tr></thead>' +
'    <tbody>' + configHtml + '</tbody></table>';

// In den bestehenden HTML-String VOR dem schliessenden </body> einfuegen,
// ohne die restliche Original-Struktur zu veraendern.
const htmlErweitert = html.replace('</body>', zusatzHtml + '</body>');

return [{ json: { html: htmlErweitert } }];
